local _, ns = ...
local Translate = ns.Lore.Translate

Translate("frFR", "skywall", {
	title = "Skywall",
	aliases = { "royaume de l'air", "plan de l'air" },
	sections = {
		{
			title = "Résumé",
			text = [=[Skywall est le royaume de l'air, l'un des quatre domaines du plan Élémentaire. C'est un ciel sans fin, fait de tempêtes et de courants, sans sol en dessous ni voûte au-dessus. Son maître est {link:al-akir}Al'Akir{/link}, le seigneur des Vents, et ses enfants natifs sont les esprits et les élémentaires du vent. Pour la plupart des peuples d'{link:azeroth}Azeroth{/link}, Skywall n'est qu'un nom dans le savoir des chamans. Pour les {link:skyborne}Skyborne{/link}, c'est leur foyer depuis dix mille ans.]=],
		},
		{
			title = "Origines",
			text = [=[Jadis, les seigneurs élémentaires se déchaînaient sur le jeune monde. Au premier âge, ils servaient les Dieux très anciens, et quand les serviteurs des titans brisèrent ce sombre empire, les élémentaires furent chassés du monde et enchaînés dans un royaume à part. Chaque seigneur reçut son propre domaine. L'air échut à {link:al-akir}Al'Akir{/link}. Depuis, le vent de Skywall souffle hors de la vue des mortels, et rares sont ceux qui y entrèrent et en revinrent pour en parler.]=],
		},
		{
			title = "Les îles cachées",
			text = [=[Au cours des longs âges qui suivirent la {link:war-of-the-ancients}guerre des Anciens{/link}, des elfes fuyant Eldre'Thalas trouvèrent refuge dans Skywall. Des {link:vanishing-of-the-wind-spirits}esprits du vent{/link} élevèrent leur terre dans le ciel et la placèrent dans un coin paisible du royaume, où l'œil du {link:al-akir}seigneur des Vents{/link} ne se posait pas. Les {link:skyborne}shen'dorei{/link} y bâtirent un chapelet de provinces insulaires. {link:zephras-isle}Zephras Isle{/link} en était une. Anvilas et Siroccas, avec leurs villes de Shen'dramar et New Eldre'naar, en étaient d'autres. Autrefois, des courants de vent appelés courants célestes portaient les voyageurs d'île en île. Ces routes sont fermées depuis longtemps.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Le refuge a failli. Les esprits qui gardaient les îles ont disparu il y a longtemps, et les {link:anchor-pylons}pylônes d'ancrage{/link} qui maintenaient {link:zephras-isle}Zephras{/link} à sa place étaient aussi les protections qui la cachaient. Ces protections sont tombées. Un seigneur du vent d'est a vu l'île de ses propres yeux, et il a promis qu'{link:al-akir}Al'Akir{/link} en entendrait parler. Aucun {link:skyborne}shen'dorei{/link} ne peut dire quand le seigneur des Vents se tournera vers eux. Tous savent qu'il le fera.]=],
		},
	},
})

Translate("frFR", "zephras-isle", {
	title = "Zephras Isle",
	aliases = { "Zephras" },
	sections = {
		{
			title = "Résumé",
			text = [=[Zephras Isle flotte dans {link:skywall}Skywall{/link}, le royaume de l'air, loin de tout rivage d'{link:azeroth}Azeroth{/link}. C'est le foyer des {link:skyborne}Skyborne{/link}, les elfes qui se nomment eux-mêmes shen'dorei. De grands arbres dominent ses bosquets du nord, des hautes terres bleues ondulent en son centre, et sur sa bordure sud-est se dresse le port de {link:valanaar}Valanaar{/link}. Des cascades tombent de ses falaises dans le ciel ouvert. Pendant dix mille ans, l'île fut un refuge caché. Aujourd'hui, elle se désagrège, et son peuple a commencé à regarder vers le bas, vers un monde que ses ancêtres avaient fui.]=],
		},
		{
			title = "Origines",
			text = [=[Les {link:skyborne}shen'dorei{/link} descendent de rebelles d'Eldre'Thalas, la cité des Bien-nés en {link:feralas}Féralas{/link} aujourd'hui appelée {red:dire-maul}Hache-tripes{/red}. Ils se soulevèrent contre le prince {red:tortheldrin}Tortheldrin{/red}, perdirent leur guerre et s'enfuirent vers l'ouest par-delà la mer. Quand les navires du prince se rapprochèrent, des {link:vanishing-of-the-wind-spirits}esprits du vent{/link} soulevèrent un grand morceau de terre dans le ciel et l'emportèrent hors du monde. Ils l'ancrèrent dans {link:skywall}Skywall{/link} au moyen d'anciens pylônes, et là, les exilés bâtirent une petite civilisation lumineuse parmi les nuages. Son fondateur, le rebelle masqué qu'on appelait le {link:flight-from-eldre-thalas}Shal'nan{/link}, remit plus tard son pouvoir à un conseil choisi par le peuple.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Il y a plusieurs siècles, les {link:vanishing-of-the-wind-spirits}esprits du vent{/link} disparurent sans un mot. Depuis, les pylônes n'ont cessé de s'affaiblir, et des quartiers entiers se sont effondrés dans le ciel. {link:ruins-of-ban-aethal}Ban'aethal{/link} tomba en une seule nuit. Le contact avec les autres îles des {link:skyborne}shen'dorei{/link} est perdu, et les réfugiés qui atteignirent Zephras s'entassent aujourd'hui à {link:valanaar}Valanaar{/link} ou se tournent vers le brigandage. Dans cette peur surgirent les {link:al-aketh}Al'Aketh{/link}, un culte d'{link:al-akir}Al'Akir{/link} mené par la grande prêtresse {link:high-priestess-lorthuna}Lorthuna{/link}. Ils s'emparèrent de {link:falaath-village}Falaath Village{/link} et du {link:shrine-of-akir}Shrine of Akir{/link}, et ils frappèrent les tours de guet des pylônes. Leur but était de briser les protections qui cachaient l'île. Les {link:windshapers}Windshapers{/link} et le {link:high-order}High Order{/link} se méprisent, mais ils se tinrent aux côtés des {link:peacekeepers}Peacekeepers{/link} de {link:valennia-stormfist}Valennia Stormfist{/link} contre le culte, et le culte fut brisé. Son œuvre ne le fut pas. Les protections ont disparu, et un seigneur de l'armée du seigneur des Vents a vu Zephras. Désormais, chaque ordre envoie ses jeunes en {link:azeroth}Azeroth{/link} : les Windshapers au {link:earthen-ring}Cercle terrestre{/link} en {link:mulgore}Mulgore{/link}, le High Order au {link:kirin-tor}Kirin Tor{/link} de {link:dalaran}Dalaran{/link}.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Le Conseil des anciens.{/b} Le haut ancien {link:talaanis-shadowsong}Talaanis Shadowsong{/link} dirige le conseil de l'île depuis {link:valanaar}Valanaar{/link}.
• {b}Les {link:windshapers}Windshapers{/link}.{/b} Des chamans et des voyants qui gardent les pierres sacrées et cherchent les esprits perdus.
• {b}Le {link:high-order}High Order{/link}.{/b} Des magistères de sang bien-né qui voudraient maîtriser eux-mêmes la magie de l'île.
• {b}Les {link:peacekeepers}Peacekeepers{/link}.{/b} La milice de l'île, ce que les {link:skyborne}shen'dorei{/link} possèdent de plus proche d'une armée.
• {b}Les {link:al-aketh}Al'Aketh{/link}.{/b} Des fanatiques du {link:al-akir}seigneur des Vents{/link}, dispersés mais non détruits.
• {b}Les Nightclaw.{/b} Un cercle secret de druides dans le {link:shadowgale-forest}Shadowgale Forest{/link}.
• {b}Les bêtes.{/b} Vuldren, ursera, prideclaws, hippogriffes et shrieklings, dont beaucoup sont devenus sauvages depuis que les vents se sont tus.]=],
		},
		{
			title = "Savoir de l'île",
			text = [=[• Un {link:skyborne}shen'dorei{/link} qui atteint l'âge adulte reçoit un objet de famille porté jadis par quelqu'un venu avant lui. Quand son porteur meurt, l'objet est récupéré pour le jeune suivant.
• Les morts sont brûlés, et leurs cendres sont confiées aux vents.
• Les pierres de vent, des gemmes bleues emplies de vent brut, éclairent et chauffent aujourd'hui la plupart des foyers de l'île.
• De petits cristaux de souvenir renferment des voix. Quand on les touche, ils laissent un enregistrement flotter faiblement dans l'air.]=],
		},
	},
})

Translate("frFR", "thendal-village", {
	title = "Thendal Village",
	aliases = { "Thendal Grove" },
	sections = {
		{
			title = "Résumé",
			text = [=[Thendal Village se trouve dans les bosquets du nord de {link:zephras-isle}Zephras{/link}, où les jeunes {link:skyborne}shen'dorei{/link} atteignent l'âge adulte. Ses maisons sont bâties dans et autour d'un immense arbre-aïeul, et ses rôdeurs veillent à l'équilibre des bois. {link:rorian-the-dayseeker}Rorian the Dayseeker{/link} dirige le village. Des anciens du conseil viennent ici juger les jeunes et les envoyer à travers l'île. À l'est du village se dressent les Thendal Standing Stones, un lieu de vent et de lignes telluriques. En haut d'un col, au nord-est, se trouve le Rise of Spirits, où les novices des {link:windshapers}Windshapers{/link} boivent la sapta sacrée. Des ursera ont leur tanière dans une grotte au sud. Depuis peu, le culte est venu jusqu'ici.]=],
		},
	},
})

Translate("frFR", "shen-dar-village", {
	title = "Shen'dar Village",
	sections = {
		{
			title = "Résumé",
			text = [=[Shen'dar Village est la première bourgade au sud des bosquets du nord, posée dans les collines bleues des {link:shen-dar-highlands}Shen'dar Highlands{/link}. La connétable {link:constable-aonda}Aonda{/link} y maintient la paix avec trop peu de {link:peacekeepers}Peacekeepers{/link}. Les deux ordres y ont des anciens : {link:illaya-amberwind}Illaya Amberwind{/link} pour les {link:windshapers}Windshapers{/link} et {link:rathiril-sunlance}Rathiril Sunlance{/link} pour le {link:high-order}High Order{/link}, et ils ne s'accordent pas sur grand-chose. Coriella Calmbreeze tient l'auberge. Pendant un temps, le village toléra une missionnaire des {link:al-aketh}Al'Aketh{/link} dans ses rues. Cette paix prit fin quand le culte se rassembla à Falaath pour frapper le village, et les villageois frappèrent les premiers.]=],
		},
	},
})

Translate("frFR", "shen-dar-highlands", {
	title = "Shen'dar Highlands",
	sections = {
		{
			title = "Résumé",
			text = [=[Les Shen'dar Highlands sont le cœur vallonné de {link:zephras-isle}Zephras{/link}. Leurs pierres levées sont sacrées pour les {link:windshapers}Windshapers{/link}, qui les gardent contre les magistères curieux du {link:high-order}High Order{/link}. Du sang a été versé entre les deux ordres auprès de ces pierres. Des bandits se cachent dans une grotte derrière une cascade au nord, des hippogriffes nichent au sud, et des prideclaws rôdent près du village. Sur une colline proche du pylône des hautes terres vit un vieil esprit de la forêt espiègle, Kuramaa. La vuldren ailée Vulgara chasse dans les collines, et les {link:peacekeepers}Peacekeepers{/link} ont mis sa tête à prix.]=],
		},
	},
})

Translate("frFR", "falaath-village", {
	title = "Falaath Village",
	sections = {
		{
			title = "Résumé",
			text = [=[Falaath Village gît en ruine dans les {link:shen-dar-highlands}Shen'dar Highlands{/link}, et les {link:al-aketh}Al'Aketh{/link} en ont fait leur domaine. Des missionnaires accueillent les nouveaux convertis à sa porte et les marquent du signe d'Akir. Des tempêtes prennent forme parmi ses maisons brisées, invoquées par les mandetempêtes du culte. C'est à l'auberge de Falaath que le prêtre céleste {link:skypriest-aanders}Aanders{/link} reçut en secret la grande prêtresse {link:high-priestess-lorthuna}Lorthuna{/link}, et c'est là que le culte prépara ses deux coups jumeaux contre {link:shen-dar-village}Shen'dar Village{/link} et la {link:west-pylon-watchtower}tour de guet de l'ouest{/link}. Le commandant Cyclas devait mener le premier. Il ne vécut pas assez pour le faire.]=],
		},
	},
})

Translate("frFR", "windsong-lake", {
	title = "Windsong Lake",
	sections = {
		{
			title = "Résumé",
			text = [=[Windsong Lake s'étend au milieu de {link:zephras-isle}Zephras{/link}, entre les hautes terres et le sanctuaire. Des crabes appelés windsong crawlers vivent sur ses rives et dans les rivières qui l'alimentent, et nulle part ailleurs au monde. On ne peut les prendre que quelques semaines par an. Autrefois, les crawlers étaient un mets délicat que l'on portait aux autres îles des {link:skyborne}shen'dorei{/link}. Des assemblages offerts par les {link:vanishing-of-the-wind-spirits}esprits du vent{/link} draguaient jadis le lac. Quand les pylônes commencèrent à faiblir, beaucoup d'entre eux sombrèrent au fond, et certains y reposent encore.]=],
		},
	},
})

Translate("frFR", "west-pylon-watchtower", {
	title = "West Pylon Watchtower",
	aliases = { "tour de guet de l'ouest" },
	sections = {
		{
			title = "Résumé",
			text = [=[La West Pylon Watchtower garde l'un des {link:anchor-pylons}pylônes d'ancrage{/link} à la bordure sud-ouest des {link:shen-dar-highlands}Shen'dar Highlands{/link}. Les {link:peacekeepers}Peacekeepers{/link} la tinrent jusqu'à l'arrivée des {link:al-aketh}Al'Aketh{/link}. Le prêtre céleste {link:skypriest-aanders}Aanders{/link} mena l'attaque, et les défenseurs moururent à leur poste. Parmi eux se trouvait le neveu du haut ancien {link:talaanis-shadowsong}Talaanis Shadowsong{/link}, dont la chevalière de famille fut retrouvée à la tour. Ce que le prêtre céleste fit là au pylône n'est pas rapporté. Le Conseil sut seulement que le culte était venu pour la tour, et non pour les soldats qui s'y trouvaient.]=],
		},
	},
})

Translate("frFR", "valanaar", {
	title = "Valanaar",
	sections = {
		{
			title = "Résumé",
			text = [=[Valanaar est le port et la principale cité de {link:zephras-isle}Zephras Isle{/link}, bâtie sur la bordure sud-est de l'île. Le haut ancien {link:talaanis-shadowsong}Talaanis Shadowsong{/link} y tient conseil, et {link:valennia-stormfist}Valennia Stormfist{/link} commande les {link:peacekeepers}Peacekeepers{/link} depuis la même salle. Les {link:windshapers}Windshapers{/link} ont un pavillon près du centre de la cité, et le {link:high-order}High Order{/link} en a un autre à son extrémité sud-est. La capitaine interdit toute querelle ouverte entre eux dans ses rues. Les réfugiés de {link:ruins-of-ban-aethal}Ban'aethal{/link} attendent des nouvelles dans la cité. Depuis les Valanaar Skydocks, les navires coupe-ciel traversent désormais les plans jusqu'en {link:azeroth}Azeroth{/link} : l'un vers {link:mulgore}Mulgore{/link}, l'autre vers {link:dalaran}Dalaran{/link}.]=],
		},
	},
})

Translate("frFR", "gustberry-lowlands", {
	title = "Gustberry Lowlands",
	aliases = { "Gustberry Fields" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Gustberry Lowlands sont les terres agricoles autour de {link:valanaar}Valanaar{/link}, riches en vergers et en champs ouverts. Des papillons géants y flottent, et des galestriders pillent les récoltes. Des bandits de grand chemin tiennent de petits camps dans les collines. Les shrieklings d'une grotte à l'ouest de la cité sont devenus hardis, et un érudit du {link:high-order}High Order{/link} a failli mourir parmi eux. Quand les {link:al-aketh}Al'Aketh{/link} marchèrent sur le pylône de l'est, les basses terres devinrent un champ de bataille, et les guérisseurs et les cogneurs du culte emplirent les champs au nord de la cité. Au bord de l'île, à l'ouest de Valanaar, les {link:windshapers}Windshapers{/link} gardent un sanctuaire des Flammes caché.]=],
		},
	},
})

Translate("frFR", "east-pylon-watchtower", {
	title = "East Pylon Watchtower",
	aliases = { "tour de guet de l'est" },
	sections = {
		{
			title = "Résumé",
			text = [=[L'East Pylon Watchtower se dresse juste à l'extérieur de {link:valanaar}Valanaar{/link} et garde le {link:anchor-pylons}pylône d'ancrage{/link} le plus proche de la cité. Les {link:al-aketh}Al'Aketh{/link} l'attaquèrent en force, menés par la commandante {link:commander-belguilos}Belguilos{/link}, une ancienne gardienne de la paix que le culte appelle la Briseuse. {link:yorana-windyreed}Yorana Windyreed{/link} amena une force de secours depuis la cité et tint bon, bien qu'elle s'attendît à y mourir. Quand Belguilos tomba, l'attaque se brisa. Le Conseil vit que le culte avait frappé les tours de l'ouest comme de l'est, et comprit enfin que sa cible était les pylônes eux-mêmes.]=],
		},
	},
})

Translate("frFR", "windfield-orchard", {
	title = "Windfield Orchard",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Windfield Orchard fait pousser des pommes d'orage dans les basses terres à l'ouest de {link:valanaar}Valanaar{/link}. Il appartient à Alvarion et {link:aamelia-windfield}Aamelia Windfield{/link}. Une bande de brigands aux ordres de Ferauu the Bludgeon prenait de force une part de chaque récolte. Quand Alvarion fut grièvement blessé, il se rendit à la cité pour engager de l'aide, tandis que sa femme restait pour défendre leurs arbres. Dans le verger se dresse aussi un vieil assemblage cyclonique des {link:vanishing-of-the-wind-spirits}esprits du vent{/link}, brisé et marmonnant. Il pose la même question encore et encore : quel est son but ?]=],
		},
	},
})

Translate("frFR", "shrine-of-akir", {
	title = "Shrine of Akir",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Shrine of Akir s'élève au nord de {link:valanaar}Valanaar{/link}, au-dessus des champs et des chutes de l'est de l'île. C'est la place forte des {link:al-aketh}Al'Aketh{/link} et le siège de la grande prêtresse {link:high-priestess-lorthuna}Lorthuna{/link}. C'est ici que le magistère du {link:high-order}High Order{/link} {link:belathaan-brightwish}Belathaan Brightwish{/link} vint parler de paix, et c'est ici qu'il mourut. C'est ici encore que {link:valennia-stormfist}Valennia Stormfist{/link} mena les {link:peacekeepers}Peacekeepers{/link}, les {link:windshapers}Windshapers{/link} et le High Order à l'assaut. Ses combattants frappèrent de front pendant qu'elle conduisait les ordres par le flanc jusqu'au sanctuaire intérieur. Beaucoup tombèrent des deux côtés. Lorthuna s'enfuit par un portail vers les flèches au-dessus.]=],
		},
	},
})

Translate("frFR", "rohashi-spires", {
	title = "Rohashi Spires",
	sections = {
		{
			title = "Résumé",
			text = [=[Les Rohashi Spires flottent dans le ciel ouvert au-dessus du {link:shrine-of-akir}Shrine of Akir{/link}, et l'on ne peut les atteindre que par un portail depuis le sanctuaire. C'est ici que {link:high-priestess-lorthuna}Lorthuna{/link} livra son dernier combat. Elle n'était pas venue briser les protections, car elles étaient déjà brisées. Elle était venue allumer un fanal. {link:rohash}Rohash{/link}, le seigneur du vent d'est, y répondit. Un instant, les elfes se tinrent seuls face à l'armée du {link:al-akir}seigneur des Vents{/link}. Puis les chamans du {link:earthen-ring}Cercle terrestre{/link} et les mages du {link:kirin-tor}Kirin Tor{/link} arrivèrent, et les flèches devinrent le lieu où les {link:skyborne}Skyborne{/link} rencontrèrent pour la première fois leurs nouveaux alliés.]=],
		},
	},
})

Translate("frFR", "shadowgale-forest", {
	title = "Shadowgale Forest",
	aliases = { "Shadowgale" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Shadowgale Forest couvre le nord-est de {link:zephras-isle}Zephras{/link}, et la plupart des {link:skyborne}shen'dorei{/link} le croient hanté. Ils n'ont pas tort. De pâles {link:vanishing-of-the-wind-spirits}esprits du vent{/link} appelés hollows dérivent entre ses arbres, et ils sont apparus pour la première fois après la disparition des esprits du vent. Le culte évite d'ordinaire la forêt, une peur que ses druides sont heureux d'entretenir. Dans une grotte au nord-est, les druides Nightclaw ont leur repaire. Les {link:al-aketh}Al'Aketh{/link} s'abattirent sur lui sans prévenir, guidés par l'un des druides eux-mêmes. Un ermite qui n'a parlé à personne depuis des années vit aussi parmi les arbres.]=],
		},
	},
})

Translate("frFR", "ruins-of-ban-aethal", {
	title = "Ruins of Ban'aethal",
	aliases = { "Ban'aethal" },
	sections = {
		{
			title = "Résumé",
			text = [=[Ban'aethal était un village au plus profond du {link:shadowgale-forest}Shadowgale Forest{/link}, à la bordure nord-est de l'île. Une nuit, sans prévenir, le sol sous lui commença à tomber dans le ciel. Ses habitants s'enfuirent avec ce qu'ils pouvaient porter et attendent aujourd'hui à {link:valanaar}Valanaar{/link}. Certains retournèrent chercher leurs biens et ne revinrent pas. Parmi les ruines, des esprits fantomatiques se rassemblent et chantent un chant étrange et triste, comme s'ils étaient liés à ce lieu. On dit qu'un grand dragon élémentaire y dort.]=],
		},
	},
})

Translate("frFR", "talaanis-shadowsong", {
	title = "Talaanis Shadowsong",
	subtitle = "Haut ancien de Zephras Isle",
	found = "La salle du conseil de Valanaar",
	hint = [=[Cherchez le haut ancien dans la salle du conseil de Valanaar.]=],
	allegiance = "Conseil des anciens · Zephras Isle",
	aliases = { "Haut ancien Shadowsong" },
	sections = {
		{
			title = "Résumé",
			text = [=[Talaanis Shadowsong est le haut ancien de {link:zephras-isle}Zephras Isle{/link} et le chef de son Conseil des anciens. Il gouverne depuis {link:valanaar}Valanaar{/link}, aux côtés de la capitaine des {link:peacekeepers}Peacekeepers{/link}. Il n'appartient ni aux {link:windshapers}Windshapers{/link} ni au {link:high-order}High Order{/link}, et il doit maintenir uni un peuple prêt à se déchirer. Ceux qui le servent disent de lui que c'est un homme bon. Même en ces années difficiles, le peuple de l'île l'aime.]=],
		},
		{
			title = "Importance",
			text = [=[Talaanis se tient à la tête de l'ordre ancien que le {link:flight-from-eldre-thalas}Shal'nan{/link} a laissé derrière lui : un conseil choisi par les {link:skyborne}shen'dorei{/link} eux-mêmes. De son temps, cet ordre a été mis à l'épreuve comme jamais. Les esprits sont partis, les pylônes faiblissent, un culte du {link:al-akir}seigneur des Vents{/link} tient la moitié de l'île, et les deux grands ordres de son peuple se parlent à peine. C'est dans sa salle que le véritable dessein du culte fut découvert, et c'est sa bénédiction qui envoya les jeunes de {link:zephras-isle}Zephras{/link} vers {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il dirige {link:shadow-council}le Conseil{/link} des anciens depuis {link:valanaar}Valanaar{/link}.
• Il transmit aux {link:peacekeepers}Peacekeepers{/link} une piste sur le culte : un renégat des {link:al-aketh}Al'Aketh{/link} qui souhaitait changer de camp.
• Il entendit le cristal de souvenir qui révéla le plan de {link:high-priestess-lorthuna}Lorthuna{/link}.
• Il bénit les expéditions des deux ordres vers {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "Non consigné",
			text = [=[On a peu écrit sur la vie de Talaanis avant ces jours. Aucune chronique ne rapporte depuis combien de temps il est haut ancien, ni qui était son neveu.]=],
		},
	},
	chapters = {
		{
			title = "La chevalière des Shadowsong",
			hint = [=[Apportez au haut ancien des nouvelles de la tour de guet de l'ouest.]=],
			text = [=[Les défenseurs de la {link:west-pylon-watchtower}tour de guet de l'ouest{/link} moururent à leur poste. Parmi les morts se trouvait le neveu du haut ancien, et sa chevalière de famille revint à {link:valanaar}Valanaar{/link} dans la main d'un étranger. Talaanis reçut la bague et la nouvelle avec dignité. Puis il fit ce qu'un ancien doit faire en de tels jours. Il envoya celui qui l'avait rapportée auprès des {link:peacekeepers}Peacekeepers{/link}, car l'île avait besoin de chaque épée volontaire.]=],
		},
		{
			title = "Le cristal de souvenir",
			hint = "Apportez au haut ancien ce que portait le renégat.",
			text = [=[Le renégat mourut avant de pouvoir parler, mais sous son corps gisait un cristal de souvenir endommagé. Talaanis le fit réveiller par {link:valennia-stormfist}Valennia{/link}. Des voix brisées s'en échappèrent : celle de {link:high-priestess-lorthuna}Lorthuna{/link}, qui parlait des pylônes et de protections qui devaient tomber. Valennia se rappela que le {link:flight-from-eldre-thalas}Shal'nan{/link} avait dit autrefois que les pylônes étaient des protections autant que des ancres, des boucliers contre tout ce qui pouvait habiter {link:skywall}Skywall{/link}. Talaanis comprit aussitôt. Le culte voulait ouvrir l'île à son {link:al-akir}seigneur des Vents{/link}.]=],
		},
		{
			title = "Le destin de Zephras",
			hint = "Rapportez au haut ancien ce qui fut appris sur les flèches.",
			text = [=[Après les flèches, les chefs des deux ordres vinrent trouver Talaanis avec la même sombre nouvelle. Les protections avaient disparu, et l'île s'offrait à {link:al-akir}Al'Akir{/link} dans son propre royaume. Chaque ordre voulait chercher sa réponse en {link:azeroth}Azeroth{/link}, et Talaanis leur donna à tous deux sa bénédiction. Il espérait que ce qu'ils trouveraient apporterait à {link:zephras-isle}Zephras{/link} la stabilité qui lui manquait depuis des années.]=],
		},
	},
	mentions = {
		{ text = "La requête du haut ancien" },
		{ text = "Le renégat" },
		{ text = "Fâcheuses nouvelles" },
		{ text = "Temps désespérés" },
		{ text = "La suite, l'adieu de la {link:horde}Horde{/link}" },
		{ text = "La suite, l'adieu de l'{link:alliance}Alliance{/link}" },
	},
	bonds = {
		{ id = "valennia-stormfist", name = "Valennia Stormfist", note = "capitaine de ses Peacekeepers" },
		{ id = "aetheen-of-the-gales", name = "Aetheen of the Gales", note = "du même conseil" },
		{ id = "ayessa-dawnsinger", name = "Ayessa Dawnsinger", note = "grande voyante céleste des Windshapers" },
		{ id = "elaadrin-evengale", name = "Elaadrin Evengale", note = "magistère suprême du High Order" },
		{ id = "high-priestess-lorthuna", name = "Grande prêtresse Lorthuna", note = "voulut ouvrir son île au seigneur des Vents" },
	},
})

Translate("frFR", "elaadrin-evengale", {
	title = "Elaadrin Evengale",
	subtitle = "Magistère suprême du High Order",
	found = "Le pavillon du High Order, au sud-est de Valanaar",
	hint = [=[Trouvez le magistère suprême dans le pavillon du High Order, au bord de Valanaar.]=],
	allegiance = "High Order · Alliance",
	aliases = { "Elaadrin" },
	sections = {
		{
			title = "Résumé",
			text = [=[Elaadrin Evengale est le magistère suprême du {link:high-order}High Order{/link}, les magistères de sang bien-né de {link:zephras-isle}Zephras Isle{/link}. Depuis son pavillon de {link:valanaar}Valanaar{/link}, il mène ceux qui pensent que les {link:skyborne}shen'dorei{/link} se sont trop fiés à leurs protecteurs élémentaires. Il est fier, il a la langue acérée et il est sûr de sa voie. Sous sa direction, le High Order a trouvé un chemin à travers les plans jusqu'en {link:azeroth}Azeroth{/link}, et un nouvel allié là-bas.]=],
		},
		{
			title = "Importance",
			text = [=[Elaadrin croit que les dons des esprits disparus peuvent être égalés par l'ancienne magie des {red:highborne}Bien-nés{/red}, si seulement son peuple parvient à la réapprendre. Cette magie s'est affaiblie dans {link:skywall}Skywall{/link}. Alors il a regardé au-dehors. Ses magistères ont taillé une sorte de trou de serrure à travers les plans et ont épié le monde que leurs ancêtres avaient quitté, et quelqu'un, de l'autre côté, leur a rendu leur regard : le {link:kirin-tor}Kirin Tor{/link} de {link:dalaran}Dalaran{/link}. Par lui, le {link:high-order}High Order{/link} a rejoint l'{link:alliance}Alliance{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il dirige le {link:high-order}High Order{/link} depuis son pavillon de {link:valanaar}Valanaar{/link}.
• Il envoya le magistère {link:belathaan-brightwish}Belathaan Brightwish{/link} au {link:shrine-of-akir}Shrine of Akir{/link} pour chercher la paix avec le culte.
• Il étudia la magie des pierres sacrées des {link:windshapers}Windshapers{/link} contre leur volonté.
• Il fit appel au {link:kirin-tor}Kirin Tor{/link} quand l'assaut contre le sanctuaire fut préparé.
• Il se tint aux côtés d'{link:ayessa-dawnsinger}Ayessa Dawnsinger{/link} contre {link:high-priestess-lorthuna}Lorthuna{/link} sur les {link:rohashi-spires}Rohashi Spires{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Le trou de serrure",
			hint = "Écoutez les projets du magistère suprême pour le High Order.",
			text = [=[Elaadrin raconta aux jeunes de son ordre ce que le trou de serrure lui avait montré. La terre que son peuple avait fuie n'était qu'une partie d'un vaste monde appelé désormais {link:azeroth}Azeroth{/link}. Ses mages s'y étaient fait des amis, un ordre très semblable au leur. Certains {link:skyborne}shen'dorei{/link}, dit-il, devaient quitter {link:skywall}Skywall{/link}, retrouver ce que leurs ancêtres avaient perdu et le rapporter chez eux pour sauver l'île.]=],
		},
		{
			title = "La langue d'argent",
			hint = [=[Répondez au magistère suprême une fois connu le sort de son envoyé.]=],
			text = [=[Quand le culte se tourna pour la première fois vers la violence, Elaadrin avait conseillé de négocier. Il envoya son ami {link:belathaan-brightwish}Belathaan{/link} au sanctuaire. Une boîte revint à {link:valanaar}Valanaar{/link}, contenant la langue de Belathaan, peinte d'argent. Elaadrin ne voulut plus de dialogue. Il offrit aux {link:peacekeepers}Peacekeepers{/link} le plein soutien du {link:high-order}High Order{/link}.]=],
		},
		{
			title = "Dans l'œil de la tempête",
			hint = [=[Tenez-vous aux côtés du magistère suprême sur les flèches au-dessus du sanctuaire.]=],
			text = [=[Sur les flèches, Elaadrin offrit à {link:high-priestess-lorthuna}Lorthuna{/link} une mort rapide si elle se rendait. Elle se moqua de lui. Quand le serviteur du {link:al-akir}seigneur des Vents{/link} arriva, Elaadrin n'avait guère que son courage à lui opposer, jusqu'à ce que les mages du {link:kirin-tor}Kirin Tor{/link} arrivent et qu'il salue pour la première fois l'archimage {link:archmage-ansirem-runeweaver}Ansirem Runeweaver{/link}.]=],
		},
		{
			title = "Le coupe-ciel vers Dalaran",
			hint = "Embarquez à Valanaar pour la cité des mages.",
			text = [=[Elaadrin avait voulu être le premier de son peuple à poser le pied sur {link:azeroth}Azeroth{/link}. Le culte changea ses plans. Il reste à {link:valanaar}Valanaar{/link} pour l'instant, et il envoie devant lui les jeunes magistères à {link:dalaran}Dalaran{/link}, où l'un de ses mages les attend.]=],
		},
	},
	mentions = {
		{ text = "Le magistère suprême" },
		{ text = "Attraper le vent" },
		{ text = "Au service de {link:zephras-isle}Zephras{/link}" },
		{ text = "La mission de Fillion" },
		{ text = "Le destin de {link:zephras-isle}Zephras{/link}" },
		{ text = "La suite" },
	},
	bonds = {
		{ id = "ayessa-dawnsinger", name = "Ayessa Dawnsinger", note = "sa rivale, pour l'heure son alliée" },
		{ id = "belathaan-brightwish", name = "Belathaan Brightwish", note = "son ami et envoyé" },
		{ id = "rathiril-sunlance", name = "Rathiril Sunlance", note = "ancien de son ordre à Shen'dar" },
		{ id = "valennia-stormfist", name = "Valennia Stormfist", note = "la capitaine qu'il accepta de suivre" },
		{ id = "high-priestess-lorthuna", name = "Grande prêtresse Lorthuna", note = "la prêtresse qu'il combattit sur les flèches" },
		{ id = "talaanis-shadowsong", name = "Talaanis Shadowsong", note = "haut ancien de Zephras Isle" },
	},
})

Translate("frFR", "ayessa-dawnsinger", {
	title = "Ayessa Dawnsinger",
	subtitle = "Grande voyante céleste des Windshapers",
	found = "Le pavillon des Windshapers, au centre de Valanaar",
	hint = [=[Trouvez la grande voyante céleste dans le pavillon des Windshapers à Valanaar.]=],
	allegiance = "Windshapers · Horde",
	aliases = { "Ayessa", "Grande voyante céleste" },
	sections = {
		{
			title = "Résumé",
			text = [=[Ayessa Dawnsinger est la grande voyante céleste des {link:windshapers}Windshapers{/link}, les chamans et voyants de {link:zephras-isle}Zephras Isle{/link}. Elle est farouche, fière et prompte à la colère, et elle veille jalousement sur son titre et sur les lieux sacrés de son ordre. Elle croit que son peuple doit rappeler ses esprits perdus, et c'est en les cherchant qu'elle a trouvé le {link:earthen-ring}Cercle terrestre{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[Ayessa est la voix des {link:skyborne}shen'dorei{/link} qui restent fidèles aux {link:vanishing-of-the-wind-spirits}esprits du vent{/link}. Elle ne nie pas la crise. Elle dit ouvertement que les {link:windshapers}Windshapers{/link} partagent peut-être la faute du départ des esprits, et elle appelle les {link:al-aketh}Al'Aketh{/link} un miroir sombre de son propre ordre. En sondant les plans de sa vue céleste, elle découvrit des chamans d'{link:azeroth}Azeroth{/link} dont la vue portait au-delà des cieux. Par {link:muln-earthfury}Muln Earthfury{/link}, les Windshapers vinrent au Cercle, et par le Cercle à la {link:horde}Horde{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle dirige les {link:windshapers}Windshapers{/link} depuis leur pavillon de {link:valanaar}Valanaar{/link}.
• Elle envoya un novice punir le magistère du {link:high-order}High Order{/link} {link:belathaan-brightwish}Belathaan{/link} pour avoir touché aux assemblages des esprits.
• Elle exige le sang pour le sang quand des Windshapers sont tués.
• Elle fit appel au {link:earthen-ring}Cercle terrestre{/link} avant l'assaut contre le sanctuaire.
• Elle affronta {link:high-priestess-lorthuna}Lorthuna{/link}, jadis sa sœur dans l'ordre, sur les {link:rohashi-spires}Rohashi Spires{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Une grande aventure",
			hint = [=[Écoutez le projet de la grande voyante céleste pour les Windshapers.]=],
			text = [=[Ayessa raconta aux jeunes {link:windshapers}Windshapers{/link} ce qu'elle avait trouvé. Le berceau de leur peuple, {link:kalimdor}Kalimdor{/link}, faisait désormais partie d'un monde bien plus vaste. Ses chamans étaient plus puissants qu'aucun de {link:zephras-isle}Zephras{/link}, et leur connaissance des plans pourrait sauver l'île. Elle demanda à de jeunes {link:skyborne}shen'dorei{/link} vigoureux de se joindre à une expédition vers eux.]=],
		},
		{
			title = "L'assemblage brisé",
			hint = "Découvrez qui a volé les pièces de l'assemblage de Valanaar.",
			text = [=[L'un des derniers assemblages en état de marche à {link:valanaar}Valanaar{/link} fut retrouvé dépouillé de ses composants. La piste mena au magistère du {link:high-order}High Order{/link} {link:belathaan-brightwish}Belathaan Brightwish{/link}. Pour Ayessa, c'était la preuve de l'arrogance dont elle accusait depuis longtemps les magistères. Elle fit savoir qu'elle ne répondrait aux menaces du High Order que lorsque son chef viendrait la trouver en personne.]=],
		},
		{
			title = "Mon ancienne sœur",
			hint = [=[Tenez-vous aux côtés de la grande voyante céleste sur les flèches au-dessus du sanctuaire.]=],
			text = [=[Sur les flèches, Ayessa supplia {link:high-priestess-lorthuna}Lorthuna{/link} d'arrêter, l'avertissant que briser les protections pourrait les condamner tous. Lorthuna la railla, la traitant de sœur déchue qui fréquentait le {link:high-order}High Order{/link}. Quand le seigneur du vent d'est arriva, {link:muln-earthfury}Muln Earthfury{/link} vint avec les chamans du Cercle. Ayessa le rencontra pour la première fois au milieu d'une bataille.]=],
		},
		{
			title = "L'avant-garde",
			hint = "Embarquez à Valanaar pour la terre du Cercle terrestre.",
			text = [=[Ayessa avait voulu aller elle-même en {link:azeroth}Azeroth{/link}. Le culte la retint à {link:valanaar}Valanaar{/link}. À sa place, elle envoie une poignée de jeunes {link:windshapers}Windshapers{/link} comme avant-garde, en {link:mulgore}Mulgore{/link}, où {link:alaana-stormwalker}Alaana Stormwalker{/link} les attend. Elle a juré que son peuple trouverait un moyen de sauver son foyer.]=],
		},
	},
	mentions = {
		{ text = "La grande voyante céleste" },
		{ text = "Une réponse ferme" },
		{ text = "Le sang pour le sang" },
		{ text = "Au service de {link:zephras-isle}Zephras{/link}" },
		{ text = "Le destin de {link:zephras-isle}Zephras{/link}" },
		{ text = "La suite" },
	},
	bonds = {
		{ id = "muln-earthfury", name = "Muln Earthfury", note = "chaman du Cercle terrestre qui lui répondit" },
		{ id = "elaadrin-evengale", name = "Elaadrin Evengale", note = "son rival, pour l'heure son allié" },
		{ id = "high-priestess-lorthuna", name = "Grande prêtresse Lorthuna", note = "jadis sa sœur chez les Windshapers" },
		{ id = "illaya-amberwind", name = "Illaya Amberwind", note = "ancienne de son ordre à Shen'dar" },
		{ id = "alaana-stormwalker", name = "Alaana Stormwalker", note = "attend son avant-garde en Mulgore" },
		{ id = "talaanis-shadowsong", name = "Talaanis Shadowsong", note = "haut ancien de Zephras Isle" },
	},
})

Translate("frFR", "al-akir", {
	title = "Al'Akir",
	subtitle = "Le seigneur des Vents, maître de Skywall",
	found = "Quelque part dans les tempêtes sans fin de Skywall",
	allegiance = "Le plan Élémentaire",
	aliases = { "Al'Akir le seigneur des Vents", "seigneur des Vents" },
	sections = {
		{
			title = "Résumé",
			text = [=[Al'Akir le seigneur des Vents est le seigneur de l'air et le maître de {link:skywall}Skywall{/link}. Il est l'un des quatre grands seigneurs élémentaires, l'égal de Ragnaros pour le feu, de Neptulon pour les marées et de Therazane pour la pierre. Le vent et la tempête sont ses serviteurs, et les élémentaires de l'air forment son armée. Aucune chronique mortelle ne parle de quiconque se serait tenu devant lui et en serait revenu.]=],
		},
		{
			title = "Importance",
			text = [=[Pour les {link:elements}seigneurs élémentaires{/link}, les peuples mortels comptent peu. Le seigneur des Vents ignorait que les {link:skyborne}shen'dorei{/link} existaient. Pendant dix mille ans, des esprits de son propre royaume cachèrent {link:zephras-isle}Zephras Isle{/link} à sa vue derrière les protections de ses pylônes, et les elfes grandirent dans son domaine sans le connaître. Les esprits qui les élevèrent refusaient de prononcer son nom. Quand les elfes les interrogeaient, les esprits devenaient inquiets, détournaient la question et leur disaient qu'ils n'avaient rien à craindre sur leurs îles. Certains shen'dorei en vinrent à douter qu'il fût réel. D'autres, voyant à travers le plan grâce à leur vue céleste, entrevirent sa puissance et se mirent à l'adorer.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Au premier âge du monde, lui et les autres seigneurs élémentaires servirent les Dieux très anciens, jusqu'à ce que les serviteurs des titans enchaînent les élémentaires dans un royaume à part.
• Il règne sur {link:skywall}Skywall{/link} avec une armée d'élémentaires de l'air et de seigneurs des vents.
• Son nom est vénéré par les {link:al-aketh}Al'Aketh{/link}, qui se disent ses fidèles.
• Ses missionnaires avertissent que quiconque vient à ses fidèles sous de faux prétextes sentira sa colère.
• Son serviteur {link:rohash}Rohash{/link} se vante que les armées du seigneur des Vents sont sans fin dans Skywall.
• La peur de sa venue pousse désormais les deux ordres des {link:skyborne}shen'dorei{/link} à chercher de l'aide en {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique de cet âge ne décrit le visage du seigneur des Vents, son siège dans {link:skywall}Skywall{/link} ni sa volonté. Les {link:skyborne}shen'dorei{/link} ne le connaissent que par le silence de leurs esprits et les vantardises de ses serviteurs.]=],
		},
	},
	chapters = {
		{
			title = "Le regard du seigneur des Vents",
			hint = [=[Apprenez ce que le Cercle terrestre et le Kirin Tor dirent aux ordres au sujet du seigneur des Vents.]=],
			text = [=[Quand {link:high-priestess-lorthuna}Lorthuna{/link} alluma son fanal sur les {link:rohashi-spires}Rohashi Spires{/link}, {link:rohash}Rohash{/link}, le seigneur du vent d'est, y répondit. Il s'étonna qu'un tel lieu pût exister dans le royaume du seigneur des Vents, et il loua ses « frères égarés » de l'avoir si bien caché. Il promit que son seigneur en entendrait parler. Les chamans du {link:earthen-ring}Cercle terrestre{/link} et les mages du {link:kirin-tor}Kirin Tor{/link} dirent aux elfes ce qu'ils savaient des seigneurs élémentaires. Ce qu'ils entendirent donna aux chefs des deux ordres de bonnes raisons d'avoir peur. Dans son propre domaine, Al'Akir pouvait les détruire quand il le voudrait.]=],
		},
	},
	mentions = {
		{
			text = [=[Le pas suivant, où une ancienne le nomme le prétendu souverain de {link:skywall}Skywall{/link}]=],
		},
		{
			text = [=[{link:falaath-village}Falaath Village{/link}, l'appel du culte à le servir]=],
		},
	},
	bonds = {
		{ id = "rohash", name = "Rohash", note = "seigneur du vent d'est, son serviteur" },
		{ id = "high-priestess-lorthuna", name = "Grande prêtresse Lorthuna", note = "alluma un fanal en son nom" },
		{ id = "ayessa-dawnsinger", name = "Ayessa Dawnsinger", note = "redoute son jugement" },
	},
})

Translate("frFR", "valennia-stormfist", {
	title = "Valennia Stormfist",
	subtitle = "Capitaine des Peacekeepers",
	found = "La salle du conseil de Valanaar",
	hint = [=[Cherchez la capitaine des Peacekeepers dans la salle du conseil de Valanaar.]=],
	allegiance = "Peacekeepers · Zephras Isle",
	aliases = { "Valennia" },
	sections = {
		{
			title = "Résumé",
			text = [=[Valennia Stormfist est la capitaine des {link:peacekeepers}Peacekeepers{/link}, la milice de {link:zephras-isle}Zephras Isle{/link}. Elle maintient l'ordre à {link:valanaar}Valanaar{/link} et interdit aux {link:windshapers}Windshapers{/link} et au {link:high-order}High Order{/link} de se battre dans ses rues. Elle est franche et pragmatique. Longtemps, ses Peacekeepers évitèrent la guerre ouverte avec le culte. Quand ce ne fut plus possible, elle devint celle qui prépara la guerre.]=],
		},
		{
			title = "Importance",
			text = [=[Valennia se tient entre les deux ordres querelleurs de l'île et le culte qui les menace tous deux. Elle vit que les {link:windshapers}Windshapers{/link} et le {link:high-order}High Order{/link} ne s'uniraient jamais l'un pour l'autre. Ils pourraient s'unir contre un ennemi plus grand. Son plan d'assaut contre le {link:shrine-of-akir}Shrine of Akir{/link}, préparé bien avant qu'on en ait besoin, réunit les trois forces sur le terrain.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle commande les {link:peacekeepers}Peacekeepers{/link} depuis {link:valanaar}Valanaar{/link}.
• Elle envoya des secours à la {link:east-pylon-watchtower}tour de guet de l'est{/link} quand le culte l'attaqua.
• Elle réveilla le cristal de souvenir du renégat et se rappela que les pylônes étaient aussi des protections.
• Elle obtint le soutien des deux ordres pour l'assaut contre le sanctuaire.
• Elle força l'entrée du sanctuaire intérieur du {link:shrine-of-akir}Shrine of Akir{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Temps désespérés",
			hint = "Portez le plan de la capitaine aux chefs des deux ordres.",
			text = [=[Le culte tenait une grande partie de l'île et croyait les {link:peacekeepers}Peacekeepers{/link} vaincus. Valennia comptait retourner cet orgueil contre lui. Une diversion à l'avant du sanctuaire, et une petite force de Peacekeepers, de {link:windshapers}Windshapers{/link} et de magistères par le flanc, pourraient atteindre le sanctuaire intérieur et en finir là avec {link:high-priestess-lorthuna}Lorthuna{/link}. Les deux ordres acceptèrent. Aucun ne pardonna à l'autre.]=],
		},
		{
			title = "Le sanctuaire intérieur",
			hint = [=[Suivez les forces de la capitaine jusqu'au cœur du sanctuaire.]=],
			text = [=[Les combats dans le sanctuaire furent acharnés, puis étrangement calmes. Les forces de Valennia le tinrent, blessées et clairsemées. {link:high-priestess-lorthuna}Lorthuna{/link} s'était enfuie par un portail vers les flèches au-dessus, et les chefs des deux ordres la poursuivirent. Valennia, trop blessée pour les suivre, envoya d'autres combattants les aider.]=],
		},
	},
	mentions = {
		{ text = "Vers {link:valanaar}Valanaar{/link}" },
		{ text = "Défense de la tour" },
		{ text = "Sur écoute" },
		{ text = "Préparez-vous au combat" },
		{ text = "Affronter {link:high-priestess-lorthuna}Lorthuna{/link}" },
	},
	bonds = {
		{ id = "talaanis-shadowsong", name = "Talaanis Shadowsong", note = "le haut ancien qu'elle sert" },
		{ id = "constable-aonda", name = "Connétable Aonda", note = "maintient la paix à Shen'dar" },
		{ id = "yorana-windyreed", name = "Yorana Windyreed", note = "sa lieutenante" },
		{ id = "hyusaa-quickbreeze", name = "Hyusaa Quickbreeze", note = "sa seconde au sanctuaire" },
		{ id = "high-priestess-lorthuna", name = "Grande prêtresse Lorthuna", note = "l'ennemie qu'elle traqua" },
	},
})

Translate("frFR", "aetheen-of-the-gales", {
	title = "Aetheen of the Gales",
	subtitle = "Ancienne de Zephras Isle",
	found = "Thendal Village",
	hint = [=[Cherchez l'ancienne du conseil qui veille sur les jeunes à Thendal Village.]=],
	allegiance = "Conseil des anciens · Zephras Isle",
	aliases = { "Aetheen" },
	sections = {
		{
			title = "Résumé",
			text = [=[Aetheen of the Gales est membre du Conseil des anciens de {link:zephras-isle}Zephras Isle{/link}. Elle est venue à {link:thendal-village}Thendal Village{/link} pour lire le cours des vents dans le bosquet et pour juger les jeunes {link:skyborne}shen'dorei{/link} qui y atteignent l'âge adulte. Elle observe avant de parler. Quand un jeune la rencontre, elle en sait déjà long sur lui.]=],
		},
		{
			title = "Importance",
			text = [=[Aetheen est l'œil du conseil sur la génération suivante. En un temps où l'île a besoin de chaque bras valide, elle décide lesquels des jeunes sont prêts à quitter l'abri du bosquet. Elle est aussi parmi les premiers à leur nommer clairement le danger : les {link:al-aketh}Al'Aketh{/link}, fanatiques d'un « prétendu » souverain de {link:skywall}Skywall{/link}, dont la puissance et les ambitions grandissent chaque jour.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle lit les vents de {link:thendal-village}Thendal Grove{/link} pour le conseil.
• Elle met les jeunes à l'épreuve en les envoyant contre les ursera et leur mère de tanière.
• Elle les envoie au sud auprès de la connétable {link:constable-aonda}Aonda{/link} à {link:shen-dar-village}Shen'dar Village{/link}, que le culte menace.
• Elle en envoie d'autres apprendre les voies de la nature auprès d'un vagabond près de Shen'dar.]=],
		},
		{
			title = "Non consigné",
			text = [=[On a peu écrit sur la vie d'Aetheen avant ces jours. Il n'est pas rapporté si elle appartient à l'un des ordres, ni depuis combien de temps elle siège au conseil.]=],
		},
	},
	chapters = {
		{
			title = "Le pas suivant",
			hint = [=[Réussissez l'épreuve de l'ancienne et allez là où elle vous envoie.]=],
			text = [=[Dans les grottes au sud du bosquet, les ursera étaient devenus affamés et désespérés, menés par une mère de tanière que les rôdeurs appelaient Urs'anah. Aetheen y envoya le jeune pour éprouver sa résolution. L'épreuve réussie, elle ne le félicita pas longtemps. Elle l'envoya au sud, où le culte pressait {link:shen-dar-village}Shen'dar Village{/link}, et lui dit d'annoncer que c'était elle qui l'envoyait.]=],
		},
	},
	mentions = {
		{ text = "Aetheen of the Gales" },
		{ text = "Matriarche immonde" },
		{ text = "L'aventurier" },
	},
	bonds = {
		{ id = "rorian-the-dayseeker", name = "Rorian the Dayseeker", note = "lui envoie les jeunes" },
		{ id = "constable-aonda", name = "Connétable Aonda", note = "une femme bonne, selon ses mots" },
		{ id = "talaanis-shadowsong", name = "Talaanis Shadowsong", note = "haut ancien de son conseil" },
	},
})

Translate("frFR", "high-priestess-lorthuna", {
	title = "Grande prêtresse Lorthuna",
	subtitle = "Grande prêtresse des Al'Aketh",
	found = "Le Shrine of Akir et les flèches au-dessus",
	hint = [=[Affrontez la grande prêtresse du culte du seigneur des Vents.]=],
	allegiance = "Al'Aketh",
	aliases = { "Lorthuna" },
	sections = {
		{
			title = "Résumé",
			text = [=[La grande prêtresse Lorthuna dirige les {link:al-aketh}Al'Aketh{/link}, le culte d'{link:al-akir}Al'Akir{/link} sur {link:zephras-isle}Zephras Isle{/link}. Elle fut jadis une {link:windshapers}Windshaper{/link} et une sœur de l'ordre d'{link:ayessa-dawnsinger}Ayessa Dawnsinger{/link}. Aujourd'hui, elle règne sur le {link:shrine-of-akir}Shrine of Akir{/link} et parle d'une grande œuvre qui amènera le seigneur des Vents à son peuple. Elle est froide, habile et cruelle, et ses fidèles se disent les instruments de sa volonté.]=],
		},
		{
			title = "Importance",
			text = [=[Lorthuna vit ce que le reste de son peuple ne voyait pas : que les pylônes de {link:zephras-isle}Zephras{/link} étaient des protections autant que des ancres. Elle fit de ce secret une arme. Son culte s'empara de {link:falaath-village}Falaath Village{/link}, frappa les tours de guet des pylônes et abattit les protections. Quel que soit son sort, son œuvre ne peut être défaite. Zephras s'offre désormais à son {link:al-akir}seigneur des Vents{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle envoya des pillards et des prêcheurs à travers l'île depuis le {link:shrine-of-akir}Shrine of Akir{/link}.
• Elle rencontra le prêtre céleste {link:skypriest-aanders}Aanders{/link} à Falaath et lança ses attaques contre Shen'dar et la {link:west-pylon-watchtower}tour de guet de l'ouest{/link}.
• Elle fit tuer l'envoyé du {link:high-order}High Order{/link} {link:belathaan-brightwish}Belathaan Brightwish{/link} et renvoya sa langue à {link:valanaar}Valanaar{/link}.
• Elle alluma un fanal sur les {link:rohashi-spires}Rohashi Spires{/link} pour les serviteurs du {link:al-akir}seigneur des Vents{/link}.]=],
		},
	},
	chapters = {
		{
			title = "L'invitée de Falaath",
			hint = [=[Apprenez ce que le culte prépare pour les Shen'dar Highlands.]=],
			text = [=[Une recrue qui se mêla aux fidèles de Falaath reçut l'ordre de se tenir loin de l'auberge, où le prêtre céleste recevait une invitée. L'invitée était Lorthuna. Ses ordres furent brefs. Elle avait d'autres affaires, et ce n'était qu'une pièce de son jeu. {link:skypriest-aanders}Aanders{/link} prendrait la {link:west-pylon-watchtower}tour de guet de l'ouest{/link}, et Cyclas prendrait {link:shen-dar-village}Shen'dar Village{/link}.]=],
		},
		{
			title = "Le fanal",
			hint = [=[Suivez la grande prêtresse jusqu'aux flèches au-dessus de son sanctuaire.]=],
			text = [=[Sur les flèches, Lorthuna dit à ses ennemis qu'ils arrivaient trop tard. Les protections étaient tombées depuis des jours. Elle allumait un fanal. Quand le seigneur du vent d'est arriva, elle le salua et demanda à être menée devant le {link:al-akir}seigneur des Vents{/link} comme la messagère de sa gloire. {link:rohash}Rohash{/link} l'écarta d'un coup et la projeta dans le ciel sans fin.]=],
		},
	},
	mentions = {
		{ text = "Brutes des {link:al-aketh}Al'Aketh{/link}" },
		{ text = "Vengé au décuple" },
		{ text = "Les véritables plans du culte" },
	},
	bonds = {
		{ id = "ayessa-dawnsinger", name = "Ayessa Dawnsinger", note = "son ancienne sœur" },
		{ id = "skypriest-aanders", name = "Prêtre céleste Aanders", note = "son serviteur à Falaath" },
		{ id = "belathaan-brightwish", name = "Belathaan Brightwish", note = "l'envoyé qu'elle tua" },
		{ id = "rohash", name = "Rohash", note = "répondit à son fanal" },
		{ id = "al-akir", name = "Al'Akir", note = "le seigneur qu'elle servait" },
	},
})

Translate("frFR", "rohash", {
	title = "Rohash",
	subtitle = "Seigneur du vent d'est",
	found = "Les Rohashi Spires, au-dessus du Shrine of Akir",
	hint = [=[Affrontez le seigneur du vent qui répondit au fanal du culte.]=],
	allegiance = "Al'Akir · Skywall",
	sections = {
		{
			title = "Résumé",
			text = [=[Rohash est le seigneur du vent d'est, l'un des grands seigneurs de l'air qui servent {link:al-akir}Al'Akir{/link} dans {link:skywall}Skywall{/link}. Il est puissant, moqueur, et il se délecte de la souffrance des êtres inférieurs. Il vint à {link:zephras-isle}Zephras Isle{/link} quand le fanal de {link:high-priestess-lorthuna}Lorthuna{/link} l'appela.]=],
		},
		{
			title = "Importance",
			text = [=[Rohash est le premier serviteur du {link:al-akir}seigneur des Vents{/link} dont on sache qu'il a vu {link:zephras-isle}Zephras Isle{/link}. Il n'avait jamais entendu parler de l'île ni de son peuple. Sa découverte le stupéfia, et il comprit aussitôt ce qu'elle signifiait. Les esprits qui avaient abrité les elfes étaient ses propres « frères égarés », et ils avaient bien caché l'île. Les protections tombées, il pouvait porter le secret à son seigneur.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il répondit au fanal de {link:high-priestess-lorthuna}Lorthuna{/link} sur les {link:rohashi-spires}Rohashi Spires{/link}.
• Il écarta la grande prêtresse quand elle eut la présomption de lui donner des ordres.
• Il appela les armées du {link:al-akir}seigneur des Vents{/link} contre les elfes.
• Il se retira quand le {link:earthen-ring}Cercle terrestre{/link} et le {link:kirin-tor}Kirin Tor{/link} se tinrent aux côtés des {link:skyborne}shen'dorei{/link}.
• Il railla l'espoir des elfes de tenir bon, disant que les armées de son seigneur étaient sans fin dans ce royaume.]=],
		},
	},
	chapters = {
		{
			title = "Le seigneur du vent d'est",
			hint = [=[Tenez-vous sur les flèches quand le fanal reçoit une réponse.]=],
			text = [=[Rohash se rit des elfes et des amis qu'ils s'étaient trouvés en bas lieux. Il se demanda à voix haute si son seigneur les réduirait en esclavage ou se contenterait de les dévorer. Quand {link:muln-earthfury}Muln Earthfury{/link} lui dit que le Cercle n'avait aucune querelle avec lui, Rohash choisit de partir. Avant de s'en aller, il fit une promesse aux elfes. Ils n'étaient les hôtes du royaume de son seigneur que jusqu'à ce que vienne le jugement du {link:al-akir}seigneur des Vents{/link}. Ils ne sauraient pas quand il viendrait, mais il viendrait.]=],
		},
	},
	mentions = {
		{ text = "Affronter {link:high-priestess-lorthuna}Lorthuna{/link}" },
	},
	bonds = {
		{ id = "al-akir", name = "Al'Akir", note = "son seigneur" },
		{ id = "high-priestess-lorthuna", name = "Grande prêtresse Lorthuna", note = "alluma le fanal auquel il répondit" },
		{ id = "muln-earthfury", name = "Muln Earthfury", note = "parla pour le Cercle terrestre devant lui" },
	},
})

Translate("frFR", "altarius", {
	title = "Altarius",
	subtitle = "Le dragon endormi de Ban'aethal",
	found = "Les Ruins of Ban'aethal",
	hint = "Cherchez parmi les ruines de Ban'aethal ce qui y dort.",
	allegiance = "Skywall",
	sections = {
		{
			title = "Résumé",
			text = [=[Altarius est un grand dragon du vent, une créature de {link:skywall}Skywall{/link} même. On dit qu'il dort parmi les {link:ruins-of-ban-aethal}Ruins of Ban'aethal{/link}, à la bordure nord-est de {link:zephras-isle}Zephras Isle{/link}, là où la terre a commencé à tomber dans le ciel. Ceux qui le réveillent ne restent pas longtemps en sa présence.]=],
