Translate("frFR", "sania-silverstream", {
	title = "Sania Silverstream",
	subtitle = "Missionnaire des Al'Aketh",
	found = "Shen'dar Village",
	hint = [=[Trouvez la missionnaire du culte à la voix douce à Shen'dar Village.]=],
	allegiance = "Al'Aketh",
	sections = {
		{
			title = "Résumé",
			text = [=[Sania Silverstream prêche pour les {link:al-aketh}Al'Aketh{/link} à {link:shen-dar-village}Shen'dar Village{/link}. Elle joue le rôle d'une douce prêtresse. Son credo veut que les {link:skyborne}shen'dorei{/link} soient devenus orgueilleux et oisifs, et que les esprits les aient quittés pour cela. Seule la pénitence, dit-elle, ramènera le toucher du vent.]=],
		},
		{
			title = "Importance",
			text = [=[Sania est le visage doux du culte. Elle donne aux nouveaux convertis la marque d'Akir et les envoie à Falaath, et elle avertit que le {link:al-akir}seigneur des Vents{/link} punit quiconque vient à ses fidèles sous de faux prétextes.]=],
		},
		{
