	allegiance = "Les esprits de Zephras",
	sections = {
		{
			title = "Résumé",
			text = [=[Urs'endris est un grand esprit ours né du vent de {link:zephras-isle}Zephras Isle{/link}. Depuis des générations, il enseigne aux druides des {link:skyborne}shen'dorei{/link} à prendre la forme des ursera. Aujourd'hui, son domaine se flétrit et tombe dans le ciel, comme une si grande part de l'île.]=],
		},
