		},
		{
			title = "Hauts faits",
			text = [=[• Il enseigne aux druides de {link:zephras-isle}Zephras{/link} la forme des ursera.
• Il met à l'épreuve ceux qui cherchent sa bénédiction.
• Il pleure sa compagne alors même qu'il demande sa mort.]=],
		},
	},
	mentions = {
		{ text = "Le grand esprit ursera" },
		{ text = "Force et miséricorde" },
	},
	bonds = {
		{ id = "elegael-thornpaw", name = "Elegael Thornpaw", note = "une druidesse de l'île" },
	},
})

Translate("frFR", "ealaane-nimbuswalker", {
