	aliases = { "Ealaane" },
	sections = {
		{
			title = "Résumé",
			text = [=[Ealaane Nimbuswalker a fui {link:ruins-of-ban-aethal}Ban'aethal{/link} la nuit où le village commença à tomber dans le ciel. Elle attend à {link:valanaar}Valanaar{/link} avec les autres réfugiés. Son bien-aimé, Resaan, est retourné chercher des provisions malgré ses supplications et n'est pas revenu. Elle craint qu'il ne soit mort, et elle ne demande que son objet de famille.]=],
