Translate("frFR", "halaan-hawk-eye", {
	title = "Halaan Hawk-Eye",
	subtitle = "Rôdeur de Thendal Grove",
	found = "Thendal Village",
	hint = "Parlez au rôdeur qui vient contempler le pylône lointain.",
	allegiance = "Rôdeurs de Thendal Grove",
	sections = {
		{
			title = "Résumé",
			text = [=[Halaan Hawk-Eye est un rôdeur de {link:thendal-village}Thendal Grove{/link} doté du don de la vue lointaine. Il vient souvent contempler l'ancien {link:anchor-pylons}pylône d'ancrage{/link} au loin. Sa splendeur n'a pas changé, dit-il, et pourtant sa magie est devenue instable. Il ne peut voir entre les mondes ni puiser dans les lignes telluriques, mais il est reconnaissant de ce qu'il possède.]=],
