		{
			title = "Hauts faits",
			text = [=[• Il surveille le {link:anchor-pylons}pylône d'ancrage{/link} depuis Thendal.
• Il prête aux jeunes sa vue lointaine, pour qu'ils voient le pylône de leurs propres yeux.]=],
		},
	},
	mentions = {
		{ text = "Les ancres de {link:zephras-isle}Zephras{/link}" },
	},
	bonds = {
