})

Translate("frFR", "windshapers", {
	title = "Windshapers",
	aliases = { "Windshaper" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Windshapers sont les chamans et les voyants des {link:skyborne}Skyborne{/link}. Ils descendent des premiers shen'dorei qui reçurent des {link:vanishing-of-the-wind-spirits}esprits du vent{/link} le don de la vue céleste, le pouvoir de voir à travers le plan élémentaire. Pendant des âges, ils furent les guides spirituels de {link:zephras-isle}Zephras Isle{/link}. Ils gardent ses pierres levées sacrées, et ils entretiennent les assemblages et les instruments que les esprits ont laissés derrière eux.]=],
		},
		{
			title = "Leur credo",
			text = [=[Les Windshapers tiennent que leur peuple a envers les {link:vanishing-of-the-wind-spirits}esprits du vent{/link} une dette qui ne pourra jamais être entièrement payée. Ils ont juré de retrouver les esprits et de restaurer les anciennes coutumes. Sans les esprits, disent-ils, ils sont presque aveugles à ce qui se passe dans {link:skywall}Skywall{/link}. Certains d'entre eux craignent que la faute du départ des esprits ne soit la leur. Ils se méfient du {link:high-order}High Order{/link}, qu'ils traitent d'héritiers arrogants des Bien-nés qui cherchent à maîtriser ce qu'ils devraient honorer. Là où le High Order voit dans les lignes telluriques surgies un don, les Windshapers voient des plaies dans la terre.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Leur magie a décliné depuis le départ des esprits, et le sang les sépare du {link:high-order}High Order{/link}. Leur cheffe, la grande voyante céleste {link:ayessa-dawnsinger}Ayessa Dawnsinger{/link}, sonda les plans de sa vue céleste et trouva le {link:earthen-ring}Cercle terrestre{/link} d'{link:azeroth}Azeroth{/link}. Par le Cercle, les Windshapers ont rejoint la {link:horde}Horde{/link}. Leur avant-garde fait désormais voile de {link:valanaar}Valanaar{/link} vers {link:mulgore}Mulgore{/link}.]=],
		},
	},
})

Translate("frFR", "high-order", {
	title = "High Order",
	sections = {
		{
			title = "Résumé",
			text = [=[Le High Order réunit les magistères des {link:skyborne}Skyborne{/link}, les descendants des érudits bien-nés d'Eldre'Thalas. Ils se disent les gardiens des voies des Bien-nés. En dix mille ans passés dans {link:skywall}Skywall{/link}, une grande part de leur savoir arcanique fut oubliée, et leur puissance déclina. Ils entendent la retrouver.]=],
		},
		{
			title = "Leur credo",
			text = [=[Le High Order tient que les {link:skyborne}shen'dorei{/link} commirent une grave erreur en remettant leur destin entre les mains d'esprits volages. La disparition des esprits l'a prouvé. Ce que les esprits faisaient autrefois, l'ordre croit qu'on peut le faire avec la magie des {red:highborne}Bien-nés{/red}, et que l'île peut tenir par elle-même. Ils étudient les lignes telluriques surgies de {link:zephras-isle}Zephras{/link} et la magie élémentaire des pierres levées, quoi qu'en disent les {link:windshapers}Windshapers{/link}. Pour les Windshapers, ce sont des fauteurs de troubles. À leurs propres yeux, ils sont les seuls prêts à agir.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Le magistère suprême {link:elaadrin-evengale}Elaadrin Evengale{/link} trouva un moyen de regarder à travers les plans, et y trouva le {link:kirin-tor}Kirin Tor{/link} de {link:dalaran}Dalaran{/link} qui lui rendait son regard. Par le Kirin Tor, le High Order a rejoint l'{link:alliance}Alliance{/link}. Ses jeunes magistères font désormais voile de {link:valanaar}Valanaar{/link} vers Dalaran pour reprendre le savoir que leurs ancêtres ont perdu.]=],
		},
	},
})

Translate("frFR", "al-aketh", {
	title = "Al'Aketh",
	aliases = { "culte des Al'Aketh", "culte d'Al'Akir" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Al'Aketh sont un culte de {link:skyborne}shen'dorei{/link} qui vénèrent {link:al-akir}Al'Akir{/link} le seigneur des Vents. Certains de leurs fondateurs se servirent de leur vue céleste pour regarder à travers {link:skywall}Skywall{/link} et entrevirent la terrible puissance de son maître. Tentés par ce pouvoir, ils rompirent avec leur peuple et se vouèrent à son service. Quand les {link:vanishing-of-the-wind-spirits}esprits du vent{/link} disparurent, le culte prospéra dans la peur qui suivit.]=],
		},
		{
			title = "Leur credo",
			text = [=[Le culte prêche que les {link:skyborne}shen'dorei{/link} devinrent orgueilleux et oisifs, tenant pour acquis les dons des vents, et que les esprits les quittèrent pour cela. Seules la pénitence et le service du {link:al-akir}seigneur des Vents{/link} ramèneront le vent. Ses missionnaires jouent à la foi douce. Ses brutes, ses mandetempêtes et ses assassins font le reste. Beaucoup de ses membres furent autrefois {link:windshapers}Windshapers{/link}, gardiens de la paix ou druides, et {link:ayessa-dawnsinger}Ayessa Dawnsinger{/link} appelle le culte un miroir sombre de son propre ordre.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Sous la grande prêtresse {link:high-priestess-lorthuna}Lorthuna{/link}, le culte tint {link:falaath-village}Falaath Village{/link} et le {link:shrine-of-akir}Shrine of Akir{/link}, pilla les caravanes de l'île et frappa les tours de guet des pylônes pour abattre les protections qui cachaient {link:zephras-isle}Zephras{/link}. Sa grande prêtresse a disparu et son sanctuaire a été pris d'assaut, mais son dessein s'est accompli. Les serviteurs du {link:al-akir}seigneur des Vents{/link} savent désormais où se trouve Zephras.]=],
		},
	},
})

Translate("frFR", "peacekeepers", {
	title = "Peacekeepers",
	aliases = { "Peacekeeper" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Peacekeepers sont la milice de {link:zephras-isle}Zephras Isle{/link} et ce que les {link:skyborne}Skyborne{/link} possèdent de plus proche d'une armée. Ils répondent à la capitaine {link:valennia-stormfist}Valennia Stormfist{/link} à {link:valanaar}Valanaar{/link} et au Conseil des anciens. Leurs connétables maintiennent l'ordre dans les villages, et leurs soldats occupent les tours de guet qui gardent les {link:anchor-pylons}pylônes d'ancrage{/link}.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Longtemps, les Peacekeepers évitèrent la guerre ouverte avec les {link:al-aketh}Al'Aketh{/link}, espérant que le culte resterait une simple nuisance. Cet espoir prit fin à {link:shen-dar-village}Shen'dar Village{/link} et aux tours de guet des pylônes. Peu nombreux, ils combattirent le culte à travers l'île et menèrent l'assaut contre le {link:shrine-of-akir}Shrine of Akir{/link}. Ils se tiennent aussi entre les {link:windshapers}Windshapers{/link} et le {link:high-order}High Order{/link}, et leur capitaine ne tolère pas que les deux ordres se battent à {link:valanaar}Valanaar{/link}. Tous ne restèrent pas fidèles. {link:commander-belguilos}Belguilos{/link}, que le culte appelle aujourd'hui la Briseuse, porta autrefois leurs couleurs. Parmi ceux qui tinrent bon se trouvaient la connétable {link:constable-aonda}Aonda{/link} de Shen'dar, la lieutenante {link:yorana-windyreed}Yorana Windyreed{/link} à la tour de l'est, et {link:hyusaa-quickbreeze}Hyusaa Quickbreeze{/link}, la seconde de la capitaine.]=],
		},
	},
})

Translate("frFR", "anchor-pylons", {
	title = "Pylônes d'ancrage",
	aliases = { "pylône d'ancrage", "pylônes d'ancrage", "pylônes du vent" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les pylônes d'ancrage sont d'anciennes tours de magie élémentaire, des dons des {link:vanishing-of-the-wind-spirits}esprits du vent{/link} aux {link:skyborne}shen'dorei{/link}. Ils maintiennent {link:zephras-isle}Zephras Isle{/link} d'un seul tenant et la gardent à sa place dans {link:skywall}Skywall{/link}. Des tours de guet des {link:peacekeepers}Peacekeepers{/link} se dressent à leurs côtés, l'une dans les hautes terres de l'ouest et l'autre à l'extérieur de {link:valanaar}Valanaar{/link}.]=],
		},
		{
			title = "Leur déclin",
			text = [=[Depuis la disparition des esprits, les pylônes sont devenus instables. Leur splendeur n'a pas changé, et aucun dommage n'est visible, mais leur magie vacille. À mesure qu'elle s'affaiblit, des parties de l'île s'effritent et tombent dans le ciel. Les {link:skyborne}shen'dorei{/link} puisent désormais dans les pierres de vent pour leurs besoins quotidiens, et le {link:high-order}High Order{/link} espère maîtriser la magie des pylônes avant qu'elle ne s'éteigne pour de bon.]=],
		},
		{
			title = "Les protections",
			text = [=[Les {link:skyborne}shen'dorei{/link} avaient à moitié oublié un second rôle. Les pylônes sont aussi des protections. Ils abritaient l'île du regard de tout ce qui peut habiter {link:skywall}Skywall{/link}. Le {link:flight-from-eldre-thalas}Shal'nan{/link} en avait parlé autrefois, et les {link:al-aketh}Al'Aketh{/link} l'apprirent. Ils frappèrent les pylônes pour abattre les protections, et ils réussirent. {link:zephras-isle}Zephras{/link} flotte toujours, mais elle n'est plus cachée.]=],
		},
	},
})

Translate("frFR", "vanishing-of-the-wind-spirits", {
	title = "Disparition des esprits du vent",
	aliases = { "esprits du vent" },
	sections = {
		{
			title = "Résumé",
			text = [=[Pendant des milliers d'années, des esprits du vent vécurent sur {link:zephras-isle}Zephras Isle{/link} aux côtés des {link:skyborne}shen'dorei{/link}, comme protecteurs, maîtres et amis. Ils élevèrent l'île, entretinrent sa magie et donnèrent à ses voyants la vue céleste. Puis, il y a plusieurs siècles, ils disparurent. Ils ne donnèrent aucun avertissement, et personne sur Zephras ne sait pourquoi ils partirent ni où.]=],
		},
		{
			title = "Ce qui suivit",
			text = [=[La magie de l'île commença à décliner. Les {link:anchor-pylons}pylônes d'ancrage{/link} vacillèrent. La plupart des assemblages des esprits cessèrent de fonctionner. D'étranges esprits pâles appelés hollows apparurent dans le {link:shadowgale-forest}Shadowgale Forest{/link}. Les bêtes devinrent sauvages, et les petits esprits follets du vent devinrent violents quand on les troublait. Le contact avec les autres îles fut perdu, et des villages entiers tombèrent dans le ciel. Chaque faction interpréta cette perte à sa manière. Les {link:windshapers}Windshapers{/link} veulent retrouver les esprits et les rappeler. Le {link:high-order}High Order{/link} affirme que les elfes ne doivent plus jamais dépendre d'eux. Les {link:al-aketh}Al'Aketh{/link} prêchent que les esprits abandonnèrent un peuple orgueilleux, et qu'il ne reste que le {link:al-akir}seigneur des Vents{/link}.]=],
		},
	},
})

Translate("frFR", "flight-from-eldre-thalas", {
	title = "Fuite d'Eldre'Thalas",
	aliases = { "Rébellion d'Eldre'Thalas", "Shal'nan" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les {link:skyborne}Skyborne{/link} furent d'abord des rebelles. Après la {link:war-of-the-ancients}guerre des Anciens{/link}, les {red:highborne}Bien-nés{/red} d'Eldre'Thalas, la cité de {link:feralas}Féralas{/link} aujourd'hui appelée {red:dire-maul}Hache-tripes{/red}, se retrouvèrent privés du Puits qui avait nourri leur magie. Le prince {red:tortheldrin}Tortheldrin{/red} chercha à les soutenir par des puissances toujours plus sombres. Certains de ses sujets avaient vu où menait une telle faim, et ils refusèrent que les erreurs d'{link:azshara}Azshara{/link} soient commises à nouveau.]=],
		},
		{
			title = "Le Voilé",
			text = [=[Les rebelles étaient menés par une figure connue seulement comme le Shal'nan, le Voilé, qui cachait son visage derrière un masque d'or sans traits. Son nom devint un cri de guerre. Par le sabotage et pire encore, ses partisans entravèrent le réseau de foyers de cristal du prince et l'humilièrent encore et encore. En ces jours, le druidisme des {link:night-elves}elfes de la nuit{/link} du nord se répandit aussi dans la cité, et le prince le condamna comme vil. Les rebelles livrèrent leur dernier combat dans son sanctuaire. Ils évitèrent le pire, mais la plupart d'entre eux périrent.]=],
		},
		{
			title = "La fuite",
			text = [=[Les survivants s'enfuirent vers l'ouest, la flotte du prince à leurs trousses. Par-delà la mer, ils trouvèrent une terre gouvernée par d'anciens esprits, et c'est là qu'ils conclurent leur pacte avec le vent. Les esprits élevèrent la terre jusque dans {link:skywall}Skywall{/link}, et les exilés devinrent les {link:skyborne}shen'dorei{/link}, le peuple caché. Avec le temps, le Shal'nan renonça à son pouvoir et le remit à un conseil choisi par son peuple.]=],
		},
	},
})
